-- Thuc hien cap nhat tu bang tam sang vocabulary_characters
UPDATE vocabulary_characters vc
SET reading_type = t.reading_type,
    reading = t.reading
FROM tmp_vc_readings t
JOIN vocabulary v ON v.word = t.word AND v.hiragana = t.hiragana
JOIN writing_characters c ON c.character = t.character
WHERE vc.vocab_id = v.id
  AND vc.character_id = c.id
  AND vc.position = t.position;
